-- Server-authoritative engine v2: online Snakes and Ladders.
-- Apply after room hardening and the number/Most/Quiz/YesNo/Liar engine migrations.
-- Dice are generated by the authenticated Edge Function; movement and turns are verified in SQL.
begin;

alter table public.game_room_engine_events
  drop constraint if exists game_room_engine_events_event_type_check;
alter table public.game_room_engine_events
  add constraint game_room_engine_events_event_type_check
  check (event_type in (
    'number_started','number_restarted','number_guess',
    'most_started','most_vote','most_question','most_finished','most_restarted','most_player_left',
    'quiz_started','quiz_answer','quiz_question','quiz_finished','quiz_restarted','quiz_player_left',
    'yesno_started','yesno_answer','yesno_question','yesno_finished','yesno_restarted','yesno_player_left',
    'liar_started','liar_hint','liar_vote','liar_finished','liar_restarted','liar_player_left',
    'snakes_started','snakes_roll','snakes_finished','snakes_restarted','snakes_player_left'
  ));

create or replace function public.engine_v2_start_snakes_game(
  p_room_id uuid,
  p_actor_id uuid,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_total integer;
  v_positions jsonb;
  v_order jsonb;
  v_scores jsonb;
  v_state jsonb;
begin
  if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_expected_updated_at is null then
    raise exception 'بيانات بدء حيّة ودرج غير صالحة.' using errcode='22023';
  end if;

  select * into v_room
  from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة أخرى.' using errcode='40001';
  end if;
  if v_room.host_id is distinct from p_actor_id then
    raise exception 'بدء اللعبة من صلاحية المضيف فقط.' using errcode='42501';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_actor_id
  ) then
    raise exception 'المضيف لم يعد عضواً في الغرفة.' using errcode='42501';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'snakes' or v_room.status<>'waiting' then
    raise exception 'هذه الغرفة ليست جاهزة لمحرك حيّة ودرج.';
  end if;

  select count(*)::integer,
         coalesce(jsonb_agg(0 order by p.seat),'[]'::jsonb),
         coalesce(jsonb_agg(p.user_id::text order by p.seat),'[]'::jsonb),
         coalesce(jsonb_object_agg(p.user_id::text,0),'{}'::jsonb)
  into v_total,v_positions,v_order,v_scores
  from public.game_room_players p where p.room_id=p_room_id;

  if v_total not between 2 and 6 or v_total>v_room.max_players then
    raise exception 'عدد اللاعبين لا يناسب حيّة ودرج.';
  end if;

  v_state:=jsonb_build_object(
    'phase','playing','round',1,'turn',0,'scores',v_scores,
    'feed',jsonb_build_array('بدأت حيّة ودرج. أول رمية للمضيف.'),
    'board',jsonb_build_object(
      'positions',v_positions,'player_order',v_order,
      'turn',0,'dice',null,'finished',null,'move_count',0,
      'finish_reason',null
    )
  );

  update public.game_rooms
  set engine_version=2,status='playing',game_state=v_state,
      game_started_at=pg_catalog.clock_timestamp(),
      updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(p_room_id,p_actor_id,'snakes_started',jsonb_build_object('players',v_total));
  return v_room;
end;
$function$;

create or replace function public.engine_v2_roll_snakes(
  p_room_id uuid,
  p_actor_id uuid,
  p_dice integer,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_board jsonb;
  v_positions jsonb;
  v_order jsonb;
  v_turn integer;
  v_total integer;
  v_old integer;
  v_candidate integer;
  v_next integer;
  v_next_turn integer;
  v_finished integer;
  v_phase text;
  v_name text;
  v_scores jsonb;
  v_score integer;
  v_feed jsonb;
  v_state jsonb;
  v_reason text;
begin
  if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_dice not between 1 and 6 or p_expected_updated_at is null then
    raise exception 'قيمة النرد أو بيانات الحركة غير صالحة.' using errcode='22023';
  end if;

  select * into v_room
  from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة أخرى.' using errcode='40001';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'snakes' or v_room.status<>'playing' then
    raise exception 'محرك حيّة ودرج غير نشط.';
  end if;
  if not exists(
    select 1 from public.game_room_players p
    where p.room_id=p_room_id and p.user_id=p_actor_id
  ) then
    raise exception 'لست عضواً في هذه الغرفة.' using errcode='42501';
  end if;

  v_board:=coalesce(v_room.game_state->'board','{}'::jsonb);
  v_positions:=coalesce(v_board->'positions','[]'::jsonb);
  v_order:=coalesce(v_board->'player_order','[]'::jsonb);
  v_turn:=coalesce((v_board->>'turn')::integer,0);
  v_total:=jsonb_array_length(v_order);

  if v_total not between 2 and 6 or jsonb_array_length(v_positions)<>v_total
     or v_turn<0 or v_turn>=v_total then
    raise exception 'حالة ترتيب اللاعبين غير صالحة.';
  end if;
  if v_order->>v_turn is distinct from p_actor_id::text then
    raise exception 'مو دورك بعد.' using errcode='42501';
  end if;

  select p.display_name into v_name
  from public.game_room_players p
  where p.room_id=p_room_id and p.user_id=p_actor_id;
  if v_name is null then raise exception 'اللاعب غير موجود.'; end if;

  v_old:=coalesce((v_positions->>v_turn)::integer,0);
  if v_old<0 or v_old>100 then raise exception 'موقع اللاعب غير صالح.'; end if;
  v_candidate:=v_old+p_dice;
  v_next:=case
    when v_candidate>100 then v_old
    when v_candidate=3 then 22
    when v_candidate=8 then 30
    when v_candidate=20 then 41
    when v_candidate=27 then 56
    when v_candidate=50 then 67
    when v_candidate=71 then 91
    when v_candidate=80 then 99
    when v_candidate=17 then 4
    when v_candidate=34 then 12
    when v_candidate=62 then 19
    when v_candidate=87 then 24
    when v_candidate=95 then 75
    when v_candidate=99 then 78
    else v_candidate
  end;

  v_positions:=jsonb_set(v_positions,array[v_turn::text],to_jsonb(v_next),false);
  v_finished:=case when v_next=100 then v_turn else null end;
  v_phase:=case when v_finished is null then 'playing' else 'finished' end;
  v_next_turn:=case when v_finished is null then (v_turn+1)%v_total else v_turn end;
  v_reason:=case when v_finished is null then null else 'winner' end;
  v_board:=v_board||jsonb_build_object(
    'positions',v_positions,'turn',v_next_turn,'dice',p_dice,
    'finished',v_finished,'move_count',coalesce((v_board->>'move_count')::integer,0)+1,
    'finish_reason',v_reason,'last_player_id',p_actor_id::text,
    'last_from',v_old,'last_to',v_next
  );

  v_scores:=coalesce(v_room.game_state->'scores','{}'::jsonb);
  if v_finished is not null then
    v_score:=coalesce((v_scores->>p_actor_id::text)::integer,0)+1;
    v_scores:=jsonb_set(v_scores,array[p_actor_id::text],to_jsonb(v_score),true);
  end if;
  v_feed:=coalesce(v_room.game_state->'feed','[]'::jsonb)
    ||jsonb_build_array(
      v_name||' رمى النرد '||p_dice||' وانتقل من '||v_old||' إلى '||v_next||
      case when v_candidate>100 then '؛ يحتاج رقماً مطابقاً للوصول إلى ١٠٠.'
           when v_candidate in (3,8,20,27,50,71,80) then ' وصعد على درج.'
           when v_candidate in (17,34,62,87,95,99) then ' ونزلته حيّة.'
           else '.' end
    );
  if v_finished is not null then
    v_feed:=v_feed||jsonb_build_array(v_name||' وصل إلى ١٠٠ وفاز بالجولة!');
  end if;

  v_state:=v_room.game_state||jsonb_build_object(
    'phase',v_phase,'turn',v_next_turn,'scores',v_scores,
    'board',v_board,'feed',v_feed
  );

  update public.game_rooms
  set status=v_phase,game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(
    p_room_id,p_actor_id,
    case when v_finished is null then 'snakes_roll' else 'snakes_finished' end,
    jsonb_build_object('dice',p_dice,'from',v_old,'to',v_next,'finished',v_finished is not null)
  );
  return v_room;
end;
$function$;

create or replace function public.engine_v2_restart_snakes_game(
  p_room_id uuid,
  p_actor_id uuid,
  p_expected_updated_at timestamptz
)
returns public.game_rooms
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_total integer;
  v_positions jsonb;
  v_order jsonb;
  v_scores jsonb;
  v_round integer;
  v_state jsonb;
begin
  if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then
    raise exception 'Engine gateway only.' using errcode='42501';
  end if;
  if p_actor_id is null or p_expected_updated_at is null then
    raise exception 'بيانات إعادة اللعبة غير صالحة.' using errcode='22023';
  end if;
  select * into v_room from public.game_rooms where id=p_room_id for update;
  if not found then raise exception 'الغرفة غير موجودة.'; end if;
  if v_room.updated_at is distinct from p_expected_updated_at then
    raise exception 'تغيّرت الغرفة؛ حدّثها وحاول مرة أخرى.' using errcode='40001';
  end if;
  if v_room.host_id is distinct from p_actor_id then
    raise exception 'إعادة اللعبة من صلاحية المضيف فقط.' using errcode='42501';
  end if;
  if not exists(select 1 from public.game_room_players p where p.room_id=p_room_id and p.user_id=p_actor_id) then
    raise exception 'المضيف لم يعد عضواً في الغرفة.' using errcode='42501';
  end if;
  if v_room.engine_version<>2 or v_room.game_key<>'snakes' or v_room.status<>'finished' then
    raise exception 'لا يمكن إعادة حيّة ودرج بهذه الحالة.';
  end if;

  select count(*)::integer,
         coalesce(jsonb_agg(0 order by p.seat),'[]'::jsonb),
         coalesce(jsonb_agg(p.user_id::text order by p.seat),'[]'::jsonb),
         coalesce(jsonb_object_agg(p.user_id::text,0),'{}'::jsonb)
  into v_total,v_positions,v_order,v_scores
  from public.game_room_players p where p.room_id=p_room_id;
  if v_total not between 2 and 6 or v_total>v_room.max_players then
    raise exception 'عدد اللاعبين لا يناسب حيّة ودرج.';
  end if;

  v_round:=coalesce((v_room.game_state->>'round')::integer,1)+1;
  v_state:=jsonb_build_object(
    'phase','playing','round',v_round,'turn',0,'scores',v_scores,
    'feed',jsonb_build_array('بدأت جولة جديدة من حيّة ودرج.'),
    'board',jsonb_build_object(
      'positions',v_positions,'player_order',v_order,
      'turn',0,'dice',null,'finished',null,'move_count',0,'finish_reason',null
    )
  );
  update public.game_rooms
  set status='playing',game_state=v_state,
      game_started_at=pg_catalog.clock_timestamp(),
      updated_at=pg_catalog.clock_timestamp()
  where id=p_room_id returning * into v_room;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(p_room_id,p_actor_id,'snakes_restarted',jsonb_build_object('round',v_round));
  return v_room;
end;
$function$;

create or replace function public.reconcile_snakes_after_player_leave()
returns trigger
language plpgsql
security definer
set search_path=''
as $function$
declare
  v_room public.game_rooms;
  v_board jsonb;
  v_state jsonb;
begin
  select * into v_room from public.game_rooms where id=old.room_id for update;
  if not found or v_room.engine_version<>2 or v_room.game_key<>'snakes'
     or v_room.status<>'playing' then
    return old;
  end if;

  v_board:=coalesce(v_room.game_state->'board','{}'::jsonb)
    ||jsonb_build_object('finish_reason','player_left');
  v_state:=v_room.game_state||jsonb_build_object(
    'phase','finished','board',v_board,
    'feed',coalesce(v_room.game_state->'feed','[]'::jsonb)
      ||jsonb_build_array('انتهت الجولة لأن لاعباً غادر الغرفة.')
  );
  update public.game_rooms
  set status='finished',game_state=v_state,updated_at=pg_catalog.clock_timestamp()
  where id=old.room_id;

  insert into public.game_room_engine_events(room_id,actor_id,event_type,event_payload)
  values(old.room_id,old.user_id,'snakes_player_left',jsonb_build_object('round_ended',true));
  return old;
end;
$function$;

drop trigger if exists game_room_players_reconcile_snakes on public.game_room_players;
create trigger game_room_players_reconcile_snakes
after delete on public.game_room_players
for each row execute function public.reconcile_snakes_after_player_leave();

revoke all on function public.engine_v2_start_snakes_game(uuid,uuid,timestamptz)
  from public,anon,authenticated;
revoke all on function public.engine_v2_roll_snakes(uuid,uuid,integer,timestamptz)
  from public,anon,authenticated;
revoke all on function public.engine_v2_restart_snakes_game(uuid,uuid,timestamptz)
  from public,anon,authenticated;
revoke all on function public.reconcile_snakes_after_player_leave()
  from public,anon,authenticated;

grant execute on function public.engine_v2_start_snakes_game(uuid,uuid,timestamptz)
  to service_role;
grant execute on function public.engine_v2_roll_snakes(uuid,uuid,integer,timestamptz)
  to service_role;
grant execute on function public.engine_v2_restart_snakes_game(uuid,uuid,timestamptz)
  to service_role;

commit;
